    const lbl = document.createElement('span'); lbl.textContent = label; lbl.style.cssText = 'color:var(--text-muted);flex:1;';
    const val = document.createElement('span'); val.textContent = (settings[key] ?? (min + (max-min)/2)) + (unit||''); val.style.cssText = 'color:var(--text-normal);min-width:32px;text-align:right;margin:0 4px;';
