      const _allRules = [...(_p.globalRules || []), ...(Array.isArray(_p.rules) ? _p.rules : [])].filter(r => r && !r.disabled && r.regex && typeof r.regex === 'string' && r.regex.length > 0);
      const allKeywords = _allRules.map(r => r.regex);
