          try { const { MarkdownRenderer: MR, Component } = require('obsidian'); const component = new Component(); component.load(); MR.renderMarkdown(remarkContent, remarkEl, plugin.currentFilePath || '', component); try { const _allKwRules = [...(Array.isArray(plugin.rules)?plugin.rules:[]), ...(Array.isArray(plugin.globalRules)?plugin.globalRules:[])]; const _kwRanges = _buildKeywordRanges(remarkEl.textContent, _allKwRules); if (_kwRanges.length > 0) { const walker = document.createTreeWalker(remarkEl, NodeFilter.SHOW_TEXT); const textNodes = []; let tn; while ((tn = walker.nextNode())) textNodes.push(tn); let offset = 0; for (const textNode of textNodes) { const nodeStart = offset; const nodeEnd = offset + textNode.textContent.length; for (const range of _kwRanges) { if (range.start >= nodeStart && range.end <= nodeEnd) { const localStart = range.start - nodeStart; const localEnd = range.end - nodeStart; const before = textNode.textContent.substring(0, localStart); const kwText = textNode.textContent.substring(localStart, localEnd); const after = textNode.textContent.substring(localEnd); const kwSpan = document.createElement('span'); kwSpan.className = (plugin.settings?.relatedHlKwUniformClass || range.cssClass || '') + ' highlight-regex-text'; kwSpan.style.cssText = 'cursor:pointer;'; kwSpan.textContent = kwText; if (range.regex) { kwSpan.dataset.ruleRegex = range.regex; kwSpan.addEventListener('click', (ce) => { ce.stopPropagation(); if (typeof plugin.openKeywordWindow === 'function') plugin.openKeywordWindow(range.regex); }); } const parent = textNode.parentNode; if (before) parent.insertBefore(document.createTextNode(before), textNode); parent.insertBefore(kwSpan, textNode); if (after) parent.insertBefore(document.createTextNode(after), textNode); parent.removeChild(textNode); break; } } offset = nodeEnd; } } } catch {} remarkEl.addEventListener('click', (ce) => { const le = ce.target.closest('a.internal-link, a.is-unresolved'); if (le) { ce.preventDefault(); ce.stopPropagation(); const h = le.dataset.href || le.getAttribute('href') || le.textContent; if (h) plugin.app.workspace.openLinkText(h, '', true); } }); remarkEl.addEventListener('auxclick', (ce) => { if (ce.button !== 1) return; const le = ce.target.closest('a.internal-link, a.is-unresolved'); if (le) { ce.preventDefault(); ce.stopPropagation(); const h = le.dataset.href || le.getAttribute('href') || le.textContent; if (h) { const leaf = plugin.app.workspace.getLeaf('window'); const file = plugin.app.metadataCache.getFirstLinkpathDest(h.replace(/\.md$/, ''), '') || plugin.app.vault.getAbstractFileByPath(h); if (file) leaf.openFile(file); } } }); } catch { remarkEl.textContent = remarkContent; try { const _allKwRules = [...(Array.isArray(plugin.rules)?plugin.rules:[]), ...(Array.isArray(plugin.globalRules)?plugin.globalRules:[])]; const _kwRanges = _buildKeywordRanges(remarkEl.textContent, _allKwRules); if (_kwRanges.length > 0) { const walker = document.createTreeWalker(remarkEl, NodeFilter.SHOW_TEXT); const textNodes = []; let tn; while ((tn = walker.nextNode())) textNodes.push(tn); let offset = 0; for (const textNode of textNodes) { const nodeStart = offset; const nodeEnd = offset + textNode.textContent.length; for (const range of _kwRanges) { if (range.start >= nodeStart && range.end <= nodeEnd) { const localStart = range.start - nodeStart; const localEnd = range.end - nodeStart; const before = textNode.textContent.substring(0, localStart); const kwText = textNode.textContent.substring(localStart, localEnd); const after = textNode.textContent.substring(localEnd); const kwSpan = document.createElement('span'); kwSpan.className = (plugin.settings?.relatedHlKwUniformClass || range.cssClass || '') + ' highlight-regex-text'; kwSpan.style.cssText = 'cursor:pointer;'; kwSpan.textContent = kwText; if (range.regex) { kwSpan.dataset.ruleRegex = range.regex; kwSpan.addEventListener('click', (ce) => { ce.stopPropagation(); if (typeof plugin.openKeywordWindow === 'function') plugin.openKeywordWindow(range.regex); }); } const parent = textNode.parentNode; if (before) parent.insertBefore(document.createTextNode(before), textNode); parent.insertBefore(kwSpan, textNode); if (after) parent.insertBefore(document.createTextNode(after), textNode); parent.removeChild(textNode); break; } } offset = nodeEnd; } } } catch {} }
